void discard_matrix_and_audit(){
    DiscardFixture f;const auto original=f.rows();f.discard_load();require(f.rows()==original,"Discard load created schema/grants");rejects([&]{f.discard_repo().receipt_exists(std::string(64,'a'));});f.install_discard();require(dump(f.db,"SELECT * FROM character_owned_instance_discard_receipts").empty(),"Discard schema granted receipts");f.money();
    f.typed(34,2,0xf3,41);f.typed(30,f.representative_armor[0],0xe2,43);f.typed(31,f.representative_armor[1],0xd1,45);f.empty_weapon(11);f.scalar(9,60000,3,19);f.scalar(8,3107,127,17);
    unsigned completed=0;for(unsigned owner=0;owner<2;++owner)for(unsigned variant=0;variant<12;++variant){const auto id=variant<8?f.representative_armor[variant]:variant==8?1:variant==9?19001:16055;const auto slot=variant%2?29u:0u;const auto bytes=f.typed(slot,id,static_cast<std::uint8_t>(0x91+variant),51+variant,owner,variant==11?10:1);f.typed(7,id,0xf7,79,owner,variant==11?10:1);const auto request=f.discard_request(slot,owner);const auto peer=f.discard_load(1-owner);const auto planned=f.discard_repo().plan(request);const auto receipt=f.receipt();const auto after=f.discard_repo().commit(receipt,request,[](const auto&){},[](const auto&){});
        require(after==planned&&after.removed20==bytes&&after.slot==slot,"Discard exact selected instance differs");auto expected=request.expected;expected.bag.scalar[slot]->item_id=0;expected.bag.scalar[slot]->count=0;++expected.bag.scalar[slot]->revision;std::erase_if(expected.bag.armor,[&](const auto& v){return v.slot==slot;});std::erase_if(expected.bag.weapons,[&](const auto& v){return v.slot==slot;});std::erase_if(expected.bag.gems,[&](const auto& v){return v.slot==slot;});require(after.after==expected&&f.discard_load(owner)==expected,"Discard changed another slot/instance/source/money/bank/history");
        // Peer peripheral sees the selected owner's intended mutation, but its
        // owned bag itself remains exact; all immutable rows in writer proof
        // are checked in commit and all peer50 cells/metadata remain untouched.
        require(f.discard_load(1-owner).bag==peer.bag,"Discard altered other player bag/equipped");
        sqlite_detail::Statement read(f.db,"SELECT account_id,character_id,item_id,source,quantity,kind,logical20,origin,provenance,source_sha256,client_sha256,instance_design_id,before_state,after_state,design_id FROM character_owned_instance_discard_receipts WHERE receipt=?");read.bind(1,receipt);require(read.row()&&read.number<unsigned>(0)==owner+1&&read.number<std::uint64_t>(1)==f.ids[owner]&&read.number<unsigned>(2)==id&&read.number<unsigned>(3)==slot&&read.number<unsigned>(4)==1,"Discard audit owner/op differs");const auto raw=read.blob(6,20,20);require(std::equal(raw.begin(),raw.end(),bytes.begin())&&read.text(7)==after.origin&&read.text(8)==after.provenance&&read.text(9)==after.source_sha256&&read.text(10)==after.client_sha256&&read.text(11)==after.instance_design_id&&read.text(14)=="CUSTOM-0071","Discard lost tombstone source/provenance20");const auto before=nlohmann::json::parse(read.text(12)),saved=nlohmann::json::parse(read.text(13));require(before[2].size()==50&&saved[2].size()==50&&saved[2][slot][0]==0&&saved[2][slot][1]==0&&!read.row(),"Discard receipt omitted full50 before/after");
        const auto rows=f.rows();rejects([&]{f.discard_repo().commit(receipt,f.discard_request(7,owner),[](const auto&){});});rejects([&]{f.discard_repo().commit(f.receipt(),request,[](const auto&){});});require(f.rows()==rows,"Discard replay/stale snapshot changed saves");++completed;
    }require(completed==24,"Discard two-owner12 representative matrix incomplete");
}
